// Source: https://art-decor.org/ad/#/at-lab-/rules/templates/1.2.40.0.34.6.0.11.9.22/2021-05-26T13:50:41
// Target: http://hl7.org/fhir/practitionerrole.html
//         http://hl7.org/fhir/practitioner.html
group CdaAssignedEntityToFhirPractitionerRole(source cda_assignedEntity : AssignedEntity, target fhir_practitionerRole : PractitionerRole, target fhir_bundle : Bundle){
  cda_assignedEntity ->
    // create the Practitioner
    fhir_bundle.entry as fhir_bundle_entry,
    fhir_bundle_entry.resource = create('Practitioner') as fhir_practitioner,
    fhir_practitioner.id = uuid() as fhir_practitioner_id,
    fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_practitioner_id),
    fhir_practitionerRole.practitioner = create('Reference') as fhir_practitionerRole_practitioner_reference,
    fhir_practitionerRole_practitioner_reference.reference = append('urn:uuid:', fhir_practitioner_id),
    fhir_practitionerRole_practitioner_reference.type = 'Practitioner' then {
      
      //ToDo
      // Check that meta.profile url is correct
      fhir_bundle where ($this.meta.profile = 'http://fhir.ehdsi.eu/laboratory/StructureDefinition/Bundle-lab-myhealtheu') ->
        fhir_practitionerRole.meta as fhir_practitionerRole_meta,
        fhir_practitionerRole_meta.profile = 'http://fhir.ehdsi.eu/laboratory/StructureDefinition/PractitionerRole-eu-myhealth-eu',
        fhir_practitioner.meta as fhir_practitioner_meta,
        fhir_practitioner_meta.profile = 'http://fhir.ehdsi.eu/laboratory/StructureDefinition/Practitioner-eu-myhealth-eu'
        "FhirPractitionerAndPractitionerRoleProfile";
      // assignedEntity.id
      cda_assignedEntity.id where (nullFlavor.exists().not()) -> fhir_practitioner.identifier;

      // assignedEntity.code
      // here also "external" laboratories (performer) are identified
      cda_assignedEntity.code where (nullFlavor.exists().not()) -> fhir_practitionerRole.specialty;

      // assignedEntity.addr
      cda_assignedEntity.addr where (nullFlavor.exists().not()) -> fhir_practitioner.address;
      // assignedEntity.telecom
      cda_assignedEntity.telecom where (nullFlavor.exists().not()) -> fhir_practitioner.telecom;
      // assignedEntity.assignedPerson
      cda_assignedEntity.assignedPerson as cda_assignedPerson then {
        // assignedEntity.assignedPerson.name
        cda_assignedPerson.name where ($this.nullFlavor.exists().not()) -> fhir_practitioner.name;
        cda_assignedPerson.name as cda_assignedPerson_name where ($this.nullFlavor.exists()) -> 
          fhir_practitioner.name as fhir_practitioner_name,
          fhir_practitioner_name.extension as fhir_practitioner_name_extension then
            CdaNullFlavorToFhirDataAbsentReason(cda_assignedPerson_name, fhir_practitioner_name_extension);
      };
      // assignedEntity.representedOrganization
      cda_assignedEntity.representedOrganization as cda_representedOrganization ->
        fhir_bundle.entry as fhir_bundle_entry,
        fhir_bundle_entry.resource = create('Organization') as fhir_organization,
        fhir_organization.id = uuid() as fhir_organization_id,
        fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_organization_id),
        fhir_practitionerRole.organization = create('Reference') as fhir_practitionerRole_organization,
        fhir_practitionerRole_organization.reference = append('urn:uuid:', fhir_organization_id),
        fhir_practitionerRole_organization.type = 'Organization' then
        CdaOrganizationCompilationToFhirOrganizationWithBundle(cda_representedOrganization, fhir_bundle, fhir_organization);
  } "CdaAssignedEntityToFhirPractitionerRole";
}

// Source: https://art-decor.org/ad/#/at-lab-/rules/templates/1.2.40.0.34.6.0.11.9.22/2021-05-26T13:50:41
// Target: http://hl7.org/fhir/practitionerrole.html
//         http://hl7.org/fhir/practitioner.html
group CdaAssociatedEntityToFhirPractitionerRole(source cda_associatedEntity : AssociatedEntity, target fhir_practitionerRole : PractitionerRole, target fhir_bundle : Bundle){
  cda_associatedEntity ->
    // create the Practitioner
    fhir_bundle.entry as fhir_bundle_entry,
    fhir_bundle_entry.resource = create('Practitioner') as fhir_practitioner,
    fhir_practitioner.id = uuid() as fhir_practitioner_id,
    fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_practitioner_id),
    fhir_practitionerRole.practitioner = create('Reference') as fhir_practitionerRole_practitioner_reference,
    fhir_practitionerRole_practitioner_reference.reference = append('urn:uuid:', fhir_practitioner_id),
    fhir_practitionerRole_practitioner_reference.type = 'Practitioner' then {

      //ToDo
      // Check that meta.profile url is correct
      fhir_bundle where ($this.meta.profile = 'http://fhir.ehdsi.eu/laboratory/StructureDefinition/Bundle-lab-myhealtheu') ->
        fhir_practitionerRole.meta as fhir_practitionerRole_meta,
        fhir_practitionerRole_meta.profile = 'http://fhir.ehdsi.eu/laboratory/StructureDefinition/PractitionerRole-eu-myhealth-eu',
        fhir_practitioner.meta as fhir_practitioner_meta,                                                                                                           
        fhir_practitioner_meta.profile = 'http://fhir.ehdsi.eu/laboratory/StructureDefinition/Practitioner-eu-myhealth-eu'
        "FhirPractitionerAndPractitionerRoleProfile";

      // associatedEntity.id
      cda_associatedEntity.id -> fhir_practitioner.identifier;
      // associatedEntity.code
      cda_associatedEntity.code as cda_associatedEntity_code ->
        fhir_practitioner.qualification as fhir_practitioner_qualification,
        fhir_practitioner_qualification.code as fhir_practitioner_qualification_code then
        CECodeableConcept(cda_associatedEntity_code,fhir_practitioner_qualification_code);
      // associatedEntity.addr
      cda_associatedEntity.addr where (nullFlavor.exists().not()) -> fhir_practitioner.address;
      // associatedEntity.telecom
      cda_associatedEntity.telecom where (nullFlavor.exists().not()) -> fhir_practitioner.telecom;
      // associatedEntity.associatedPerson
      cda_associatedEntity.associatedPerson as cda_associatedPerson then {
        // associatedEntity.associatedPerson.name
        cda_associatedPerson.name where ($this.nullFlavor.exists().not()) -> fhir_practitioner.name;
        cda_associatedPerson.name as cda_associatedPerson_name where ($this.nullFlavor.exists()) -> 
          fhir_practitioner.name as fhir_practitioner_name,
          fhir_practitioner_name.extension as fhir_practitioner_name_extension then
            CdaNullFlavorToFhirDataAbsentReason(cda_associatedPerson_name, fhir_practitioner_name_extension);
      };
      // associatedEntity.scopingOrganization
      cda_associatedEntity.scopingOrganization as cda_scopingOrganization ->
        fhir_bundle.entry as fhir_bundle_entry,
        fhir_bundle_entry.resource = create('Organization') as fhir_organization,
        fhir_organization.id = uuid() as fhir_organization_id,
        fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_organization_id),
        fhir_practitionerRole.organization = create('Reference') as fhir_practitionerRole_organization,
        fhir_practitionerRole_organization.reference = append('urn:uuid:', fhir_organization_id),
        fhir_practitionerRole_organization.type = 'Organization' then
        CdaOrganizationCompilationToFhirOrganizationWithBundle(cda_scopingOrganization, fhir_bundle, fhir_organization);
  } "CdaAssociatedEntityToFhirPractitionerRole";
}

group CdaPerformerToFhirObservationPerformer(source cda_performer: Performer, target fhir_observation: Observation, target fhir_bundle: Bundle) {
  // observation.performer.time - it is assumed that only @value occurs and no interval
  cda_performer.time where (nullFlavor.exists().not()) -> fhir_observation.issued;
  // observation.performer.assignedEntity
  cda_performer.assignedEntity as cda_performer_assignedEntity ->
    // Create a PractitionerRole
    fhir_bundle.entry as fhir_bundle_entry01,
    fhir_bundle_entry01.resource = create('PractitionerRole') as fhir_practitionerRole,
    fhir_practitionerRole.id = uuid() as fhir_practitionerRole_id,
    fhir_bundle_entry01.fullUrl = append('urn:uuid:', fhir_practitionerRole_id),
    fhir_observation.performer = create('Reference') as fhir_observation_performer_reference,
    fhir_observation_performer_reference.reference = append('urn:uuid:', fhir_practitionerRole_id),
    fhir_observation_performer_reference.type = 'PractitionerRole',
    fhir_observation_performer_reference.extension as performer_function_extension,
    performer_function_extension.url = 'http://hl7.org/fhir/StructureDefinition/event-performerFunction',
    performer_function_extension.value = create('CodeableConcept') as performer_function_extension_value,
    performer_function_extension_value.coding = create('Coding') as performer_function_extension_value_coding,
    performer_function_extension_value_coding.system = 'http://terminology.hl7.org/CodeSystem/v3-ParticipationType',
    // Cave: Using PrimaryPerformer even though cda specifies PRF. 
    performer_function_extension_value_coding.code = 'PPRF' then CdaAssignedEntityToFhirPractitionerRole(cda_performer_assignedEntity, fhir_practitionerRole, fhir_bundle);
}

group CdaParticipantToFhirPractitionerRole(source cda_participant: Participant2, target fhir_practitionerRole: PractitionerRole, target fhir_bundle: Bundle){
  // time
  // TODO

  // participantRole
  cda_participant.participantRole as cda_participant_role -> 
    fhir_bundle.entry as fhir_bundle_entry,
    fhir_bundle_entry.resource = create('Practitioner') as fhir_practitioner,
    fhir_practitioner.id = uuid() as fhir_practitioner_id,
    fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_practitioner_id),
    fhir_practitionerRole.practitioner = create('Reference') as fhir_practitionerRole_practitioner_reference,
    fhir_practitionerRole_practitioner_reference.reference = append('urn:uuid:', fhir_practitioner_id),
    fhir_practitionerRole_practitioner_reference.type = 'Practitioner' then {
        // participantRole/id ->  Practitioner.identifier
        cda_participant_role.id where ($this.nullFlavor.exists().not()) -> fhir_practitioner.identifier;
        
        // participantRole/addr -> Practitioner.address
        cda_participant_role.addr -> fhir_practitioner.address;

        // participantRole/telecom -> Practitioner.telecom
        cda_participant_role.telecom -> fhir_practitioner.telecom;
       
        // participantRole/playingDevice
        // TODO

        // participantRole/playingEntity -> Practitioner.name
        cda_participant_role.playingEntity as cda_participant_role_playingEntity then {
          // participantRole/playingEntity/name -> Practitioner.name
          cda_participant_role_playingEntity.name -> fhir_practitioner.name;
        };
        
        // participantRole/scopingEntity -> PractitionerRole.organization 
        cda_participant_role.scopingEntity as cda_participant_role_scoping_entity then {
          cda_participant_role_scoping_entity.desc as cda_participant_role_scoping_entity_desc ->
            fhir_practitionerRole.organization = create('Reference') as fhir_practitionerRole_organization_reference,
            fhir_practitionerRole_organization_reference.display = (cda_participant_role_scoping_entity_desc.xmlText);
        };
    };
}